/**
 * Live availability check for a `<name>.play.nxeon.cloud` Minecraft
 * subdomain — shared by both the paid deploy wizard's game step and the free
 * Minecraft claim form, since `isSubdomainAvailable` already cross-checks
 * both `FreeMinecraftServer` and `Server` (the two products share one DNS
 * namespace; a name taken on either side is unavailable on both).
 *
 * Advisory UX only, same caveat as checkHostingSubdomain: the authoritative
 * de-dup is each create path's own pre-check plus its DB unique constraint,
 * so a check that says "available" can still lose a race at submit time and
 * fail cleanly there.
 */
export async function checkGameSubdomain(
  subRaw: string,
  opts?: { excludeServerId?: string; excludeFreeMcId?: string },
): Promise<{ available: boolean; reason?: string }> {
  await requireUser();
  const sub = String(subRaw ?? "").trim().toLowerCase();
  if (!sub) return { available: false, reason: "Enter a name." };
  const formatError = validateSubdomainFormat(sub);
  if (formatError) return { available: false, reason: formatError };
  if (!(await isSubdomainAvailable(sub, opts))) {
    return { available: false, reason: "This name is taken — try another." };
  }
  return { available: true };
}

