export async function getMyFreeMinecraftServer() {
  const user = await requireUser();
  return db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
}

export async function createFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const subdomain = String(formData.get("subdomain") ?? "");

  // Prefer the new two-axis fields (the UI being built in parallel sends
  // these); fall back to the legacy flat `preset` field the current create
  // form (components/customer/FreeMinecraftPanel.tsx) still submits, so
  // account creation keeps working unbroken through the UI migration.
  // Defaults to gameType=vanilla, gameMode=survival either way.
  const gameTypeField = formData.get("gameType");
  const gameModeField = formData.get("gameMode");
  let gameType = "vanilla";
  let gameMode = "survival";
  if (typeof gameTypeField === "string" && FREEMC_GAME_TYPES[gameTypeField]) {
    gameType = gameTypeField;
    if (typeof gameModeField === "string" && FREEMC_GAME_MODES[gameModeField]) gameMode = gameModeField;
  } else {
    const mapped = mapLegacyPresetKey(String(formData.get("preset") ?? "vanilla"));
    if (mapped) ({ gameType, gameMode } = mapped);
  }
  const gameTypeDef = FREEMC_GAME_TYPES[gameType];
  const gameModeDef = FREEMC_GAME_MODES[gameMode];

  if (!(await getSettingBool("free_minecraft_enabled", false))) {
    return { error: "Free Minecraft servers aren't open yet — check back soon." };
  }

  try {
    await assertEmailVerified(user);
  } catch {
    return { error: "Verify your email first — check your inbox for the link." };
  }

  const rl = checkRateLimit(`freemc:create:${user.id}`, { max: 5, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const sub = subdomain.trim().toLowerCase();
  const subdomainError = validateSubdomainFormat(sub);
  if (subdomainError) return { error: subdomainError };
  if (!(await isSubdomainAvailable(sub))) return { error: "That name is taken — try another." };

  const existing = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (existing) return { error: "You already have a free server. Delete it before creating another." };

  // `free_minecraft_max_concurrent` (lib/actions-settings.ts) is documented as
  // "how many free servers may be AWAKE at once" — the host-RAM circuit
  // breaker, independent of how many accounts have ever created one. This
  // USED to be checked against a row count of every non-DELETED
  // FreeMinecraftServer, which counts sleeping (stopped-container) servers
  // identically to running ones — the schema's own comment on `status`
  // explains why the DB can't tell them apart (mc-router owns awake/asleep
  // live, never mirrored back to avoid staleness). Once real accounts filled
  // the row-count cap, EVERY new signup was refused as "at capacity" even
  // when every existing container was asleep and the host was idle — the
  // literal thing this setting exists to prevent (an idle host still
  // rejecting signups). Ask the host what's actually awake instead.
  const maxTotal = await getSettingInt("free_minecraft_max_concurrent", 8);
  try {
    const host = await freemcHost();
    const capacity = await withServerSsh(host, (conn) => getFreemcHostCapacity(conn));
    if (capacity.runningContainers.length >= maxTotal) {
      return { error: "Free servers are at capacity right now — please try again later." };
    }
  } catch (e) {
    console.error("[free-minecraft] live capacity check failed, refusing rather than risking overcommit:", e);
    return { error: "Couldn't check server capacity right now — please try again in a moment." };
  }

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
  // New servers boot Paper by default (async chunk loading + the usual Paper
  // fixes; same world format as vanilla). Existing rows keep NULL = vanilla.
  const engine = defaultEngineFor(await getSetting("free_minecraft_engine_default", "PAPER"));

  // Derived from userId (unique, known up front) rather than the row's own id,
  // so creation is a single write — no awkward "create with a placeholder,
  // then patch in the real name" two-phase step that could race.
  const containerName = `mc-free-${user.id}`;
  let row;
  try {
    row = await db.freeMinecraftServer.create({
      data: {
        userId: user.id,
        subdomain: sub,
        containerName,
        status: "CREATING",
        activeGameType: gameType,
        activeGameMode: gameMode,
        preset: legacyPresetKeyFor(gameType, gameMode),
        engine,
      },
    });
  } catch {
    return { error: "That name is taken — try another." };
  }

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const setup = await exec(conn, `mkdir -p ${shellQuote(serverDataPath(row.id))}`, 15_000);
      if (setup.code !== 0) return { ok: false as const, error: setup.stderr || "mkdir failed" };
      await seedNewServerProperties(conn, row.id).catch((e) => console.error("[free-minecraft] property seed failed (non-fatal):", e));
      return recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: sub,
        domain,
        ramMb,
        ownerId: user.id,
        gameType: gameTypeDef,
        gameTypeKey: gameType,
        gameMode: gameModeDef,
        engine,
      });
    });
    if (!outcome.ok) throw new Error(outcome.error);
  } catch (e) {
    // Real, reproduced-live bug this closes: a `waitForServerReady` timeout
    // used to delete only the DB row, leaving the actual container running
    // (it can finish booting seconds after the app gives up — see
    // waitForServerReady's doc comment) — orphaned, invisible to the
    // customer, and still occupying a real capacity slot forever since
    // nothing with a DB row left ever prompts its removal. Best-effort:
    // never let a cleanup failure here mask the real error reported below.
    try {
      const host = await freemcHost();
      await withServerSsh(host, async (conn) => {
        await exec(conn, `docker rm -f ${shellQuote(containerName)}`, 15_000);
        // A failed create has no player data yet — remove its dir outright
        // instead of leaving one more orphan (43 found on 2026-10-01).
        await exec(conn, `rm -rf ${shellQuote(serverDataPath(row.id))}`, 15_000);
      });
    } catch (cleanupErr) {
      console.error("[free-minecraft] post-failure container cleanup failed:", cleanupErr);
    }
    await db.freeMinecraftServer.delete({ where: { id: row.id } }).catch(() => {});
    console.error("[free-minecraft] create failed:", e);
    // recreateGameTypeContainer's own capacity check (CPU/RAM headroom on the
    // host, stricter than the count-based check above) throws an already
    // customer-safe, specific message — surface it as-is rather than masking
    // it with the generic fallback. A real capacity wall reads very
    // differently to a customer than "something broke, try again" — the
    // latter reads as a random glitch and, confirmed live, led a customer to
    // delete a server that would have created fine moments later once
    // whatever else was using the budget finished booting or went idle.

 * applied in a second pass via applyModeProperties, once the container is
 * confirmed alive, so a later mode-only restart can always change them
 * cleanly without a recreate.
 *
 * Verifies liveness twice — once ~15s after `docker run` (long enough for an
 * init-time plugin/version failure to have already killed it), once more
 * ~8s after the follow-up mode-properties restart — and never throws; the
 * caller decides what a failure means (typically: roll back to the
 * account's previous type/mode).
 */
export async function recreateGameTypeContainer(
  conn: Client,
  params: {
    containerName: string;
    dataPath: string;
    subdomain: string;
    domain: string;
    ramMb: number;
    ownerId: string;
    gameType: FreeMcGameType;
    gameTypeKey: string;
    gameMode: FreeMcGameMode;
    /** Extra env vars layered on top of the type's own (e.g. the Mod Menu's
     *  merged MODRINTH_PROJECTS list) — last-write-wins over the type's env. */
    extraEnv?: Record<string, string>;
    /** FreeMinecraftServer.engine — NULL for legacy rows (stay VANILLA). */
    engine?: string | null;
  },
): Promise<{ ok: boolean; error?: string; untouched?: boolean }> {
  // Vanilla OOM-killed TWICE live (2026-09-05 and again 2026-09-06, same
  // account/world, freemc-host/node-2) before this fix. First attempt only
  // dropped the ratio 0.85->0.75 (1024m container => 768m heap) and raised
  // the container itself nowhere — insufficient: the second incident hit
  // 1044.6m RSS (277m of non-heap overhead: metaspace, thread stacks, NIO
  // direct buffers, JIT code cache) against a mere 256m of headroom, MORE
  // overhead than the first incident's 171m despite a SMALLER heap — this
  // overhead does not scale predictably with heap size, so shaving the ratio
  // alone chases a moving target. Fixed properly this time by giving vanilla
  // its own floor (1536m, same mechanism as the plugins floor below) instead
  // of only living inside the bare global default, at the same 0.7 ratio
  // plugins already use: 1536m*0.7 = 1075m heap, 461m headroom — comfortably
  // above both observed spikes, not just the smaller one.
  // (The 0.7 heap ratio and the per-kind floors/cpus now live in
  // lib/freemc-limits.ts's containerResources — same numbers, unit-tested.)
  // The global free_minecraft_ram_mb setting (1024 by default) is sized for
  // the properties-only presets — plugins-kind ones (EssentialsX + LuckPerms
  // + Vault + a type's own plugins, up to 6 loaded dimensions on something
  // like SkyBlock) run noticeably heavier and were found live to OOM-kill a
  // short while AFTER printing "Done" at that ceiling — not during boot, so
  // the old shallow "still alive 15s after docker run" check never caught it,
  // and the fix wasn't the plugins themselves (confirmed by re-testing with
  // WorldEdit removed — same crash, same timing) or --cpus. It really is a
  // sizing problem: 1536m/0.7 ran the same SkyBlock config stable for 100s+
  // post-boot with ONE player — but confirmed live it's still not enough
  // once a SECOND player joins: memory climbed to 90% (1.355GB/1.5GB) during
  // the second player's own island-creation schematic paste (world-gen +
  // chunk load + plugin bookkeeping for two islands across up to 6
  // dimensions at once), and the container was killed twice in that window
  // before settling. 2560m/0.7 gives real headroom for that case; the free
  // tier is a shared/social product, so "two friends on one server" is the
  // common case, not an edge case. Bump container memory for plugin-kind
  // presets specifically rather than raising the global default (which
  // properties-only presets don't need) — and, per the vanilla incident
  // history above, give vanilla its own floor too (1536m) for the same
  // reason: the bare 1024m global default has now OOM-killed a real
  // vanilla world twice with nothing but a ratio tweak between the two.
  const res = containerResources(params.gameType.kind, params.ramMb);
  const { ramMb, cpus } = res;
  // Vanilla game type on the Paper engine (new servers since 2026-10-01, see
  // FreeMinecraftServer.engine) — pinned to the same verified version as the
  // plugin types, plus ViaVersion so clients on a newer release can still
  // join (exactly what the plugin types already ship for the same reason).
  const engine = resolveEngine(params.gameType.kind, params.engine);
  const paperVanilla = engine === "PAPER" && params.gameType.kind !== "plugins";

  const envVars = {
    ...envForGameType(params.gameType),
    ...(paperVanilla ? { MODRINTH_PROJECTS: "viaversion" } : {}),
    ...(params.extraEnv ?? {}),
    ...jvmEnv(res),
    LEVEL: params.gameTypeKey,
  };
  const envFlags = Object.entries(envVars)
    .map(([k, v]) => `-e ${k}=${shellQuote(v)}`)
    .join(" ");

  // Checked FIRST, removed SECOND (changed 2026-10-01). The old order —
  // `docker rm -f` and THEN the capacity check — meant a refusal left the
  // account with no container at all: mc-router can't wake what doesn't
  // exist, so the server was simply gone until someone recreated it (this is
  // exactly how the 2026-09-05 bulk sweep deleted a connected player's
  // container). Now the snapshot is taken first with this account's OWN
  // running container subtracted (so a type switch never blocks on its own
  // old usage, same as before), and only a passing check removes anything.
  const capacity = await getFreemcHostCapacity(conn);
  const own = capacity.runningContainers.find((c) => c.containerName === params.containerName);
  const maxConcurrent = await getSettingInt("free_minecraft_max_concurrent", 8);
  const verdict = evaluateStart(
    {
      totalCpus: capacity.totalCpus,
      totalRamMb: capacity.totalRamMb,
      committedCpus: capacity.committedCpus - (own?.cpus ?? 0),
      committedRamMb: capacity.committedRamMb - (own?.ramMb ?? 0),
      runningCount: capacity.runningContainers.length - (own ? 1 : 0),
    },
    { cpus, ramMb },
    { reservedCpus: FREEMC_RESERVED_CPUS, reservedRamMb: FREEMC_RESERVED_RAM_MB, maxConcurrent },
  );
  if (!verdict.ok) {
    // `untouched`: nothing was removed or changed — callers must NOT run a
    // rollback recreate (it would hit the same wall and report a scary
    // "restoring also failed" for a server that was never modified).
    return { ok: false, untouched: true, error: "Free servers are at capacity right now — try again in a few minutes." };
  }
  await exec(conn, `docker rm -f ${shellQuote(params.containerName)}`, 30_000);

  const cmd = [
    "docker run -d",
    `--name ${shellQuote(params.containerName)}`,
    "--network freemc",
    `--memory=${ramMb}m --memory-swap=${ramMb}m --cpus=${cpus}`,
    // No docker-level auto-restart: a crashed free server is restarted (or
    // not) by the watchdog's backoff + breaker (worker/freemc-health.ts), or
    // simply woken again by mc-router on the next connect — never in a tight
    // docker restart loop that bypasses the capacity gate.
