    `--stop-timeout=${FREEMC_STOP_TIMEOUT_S}`,
    // Docker's json-file driver keeps container logs forever by default.
    "--log-opt max-size=10m --log-opt max-file=3",
    `--label nxeon.freemc.engine=${engine}`,
    `--label mc-router.host=${shellQuote(`${params.subdomain}.${params.domain}`)}`,
    `-v ${shellQuote(params.dataPath)}:/data`,
    `-e EULA=TRUE -e TYPE=${engine} -e ONLINE_MODE=FALSE`,
    params.gameType.kind === "plugins" || paperVanilla ? `-e VERSION=${shellQuote(FREEMC_PLUGIN_MC_VERSION)}` : "",
    `-e ENABLE_RCON=true -e RCON_PASSWORD=${shellQuote(rconPasswordFor(params.ownerId))}`,
    envFlags,
    "itzg/minecraft-server",
  ].join(" ");
  const run = await exec(conn, cmd, 90_000); // plugin downloads can take longer than a plain boot
  if (run.code !== 0) return { ok: false, error: run.stderr || "docker run failed" };

