"use client";

import { SettingsForm, TextField, ToggleField } from "./fields";

/**
 * Free Minecraft tier controls. One dedicated host VM ("freemc-host") runs many
 * lightweight per-account Docker containers behind mc-router, which routes by
 * subdomain and auto-starts/stops containers on connect/idle — the resource
 * caps here are the hard ceilings that make that safe on a single shared VM.
 * Saves through the shared `saveSettings` action (section "free_minecraft"),
 * same pattern as every other gated subsystem panel on this page.
 */
export function FreeMinecraftPanel({ v }: { v: Record<string, string> }) {
  return (
    <SettingsForm
      section="free_minecraft"
      title="Free Minecraft servers"
      desc="A free, ad-free-but-limited Minecraft server tier for growing the user base — one per verified account, running on a dedicated host VM. Off by default until the host is provisioned and DNS is pointed at it."
    >
      <ToggleField
        label="Enable free Minecraft servers"
        name="free_minecraft_enabled"
        defaultChecked={v.free_minecraft_enabled === "true"}
        hint="When on, verified accounts can create a free server from the dashboard and the landing page goes live. Requires the host VM, wildcard DNS, and NAT rule to already be set up."
      />
      <TextField
        label="Host public IP"
        name="free_minecraft_public_ip"
        defaultValue={v.free_minecraft_public_ip}
        hint="The freemc-host VM's public-facing IP — what the wildcard DNS record and the port-forward rule point at."
      />
      <TextField
        label="Connect domain"
        name="free_minecraft_domain"
        defaultValue={v.free_minecraft_domain}
        hint={"Wildcard base players connect through, e.g. play.nxeon.cloud — a server named \"bob\" is reachable at bob.play.nxeon.cloud."}
      />
      <TextField
        label="RAM per server (MB)"
        name="free_minecraft_ram_mb"

    }
    if (f.max !== undefined && n > f.max) {
      return { error: `“${f.key}” must be ${f.max} or less (you entered ${s}).` };
    }
    changes.push({ key: f.key, value: f.type === "int" ? String(Math.round(n)) : String(n) });
