// Cross-field: the dunning schedule must run in the order the panel's own hints
// promise — grace (dunning starts) ≤ warn (final-warning email) < terminate (VM
// destroyed). Field-level bounds cannot catch an inverted schedule, and an
// inverted one deletes a customer's server before, or without, warning them.
// worker/billing.ts also clamps on read; this check exists so the operator is
// TOLD, instead of having their numbers silently rewritten behind the panel.
if (section === "billing") {
  const day = (k: string) => Number(changes.find((c) => c.key === k)?.value);
  const grace = day("dunning_grace_days");
  const warn = day("dunning_warn_days");
  const terminate = day("dunning_terminate_days");
  if (warn < grace) {
    return { error: `Dunning warn (${warn}d) cannot come before dunning grace (${grace}d).` };
  }
  if (terminate <= warn) {
    return { error: `Dunning terminate (${terminate}d) must come after the final warning (${warn}d).` };
  }
}

// Cross-field: the win-back look-back window must be WIDER than the cooldown, or
// no user is ever both "past the cooldown" and "inside the window" at once and the
// sweep emails no one. Refuse (like the dunning check) so the operator is told,
// instead of the sweep silently falling back to a default they can't see.
if (section === "winback") {
  const num = (k: string) => Number(changes.find((c) => c.key === k)?.value);
  const delayMinutes = num("deploy_winback_delay_minutes");
  const maxAgeDays = num("deploy_winback_max_age_days");
  if (Number.isFinite(delayMinutes) && Number.isFinite(maxAgeDays)) {
    const delayDays = delayMinutes / (24 * 60);
    if (maxAgeDays <= delayDays) {
      return {
        error: `“How far back to look” (${maxAgeDays}d) must be greater than the wait (${delayMinutes} min ≈ ${delayDays.toFixed(2)}d), or the window is empty.`,
      };
    }
  }

