/**
 * Per-server game connect domain: the pure rules (2026-10-08, playnxeon.com move).
 *
 * Every game server's public address is `<subdomain>.<domain>`. Until this
 * change ONE global setting (`free_minecraft_domain`, default
 * `play.nxeon.cloud`) decided the domain for every server, so changing it would
 * have moved every existing server's address at once. Now each row carries its
 * own `connectDomain`:
 *
 *   - NULL  = legacy: the server lives under the `free_minecraft_domain`
 *             setting (play.nxeon.cloud), byte-for-byte what it did before.
 *             Every row that existed before the switch is NULL forever, so
 *             existing servers are never moved.
 *   - "playnxeon.com" (or whatever `game_domain_new` held at creation) = the
 *             server was created after `game_domain_new_enabled` was turned on.
 *
 * The NAME namespace stays ONE across both domains: `Server.subdomain` and
 * `FreeMinecraftServer.subdomain` keep their unique constraints and the shared
 * cross-table availability check (lib/game-subdomain.ts), so `bob` taken on
 * either domain is unavailable on both.
 *
 * Zero dependencies (no db, no settings) so client components (deploy wizards)
 * and unit tests can import it. The DB/settings half is lib/game-domain.ts.
 */

/** The historic domain, and the fallback when the legacy setting is blank. */
export const LEGACY_GAME_DOMAIN = "play.nxeon.cloud";
/** Default for the `game_domain_new` setting. */
export const NEW_GAME_DOMAIN_DEFAULT = "playnxeon.com";

const DOMAIN_RE = /^(?=.{3,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

/**
 * Normalise an operator- or DB-supplied domain: trim, lowercase, drop a
 * leading `*.` / `.` and a trailing `.`. Returns null for anything that is not
 * a plausible hostname, so a fat-fingered setting can never produce an
 * address like `bob.` or `bob.https://x`.
 */
export function normalizeGameDomain(raw: string | null | undefined): string | null {
  let d = String(raw ?? "").trim().toLowerCase();
  if (d.startsWith("*.")) d = d.slice(2);
  d = d.replace(/^\.+/, "").replace(/\.+$/, "");
  return DOMAIN_RE.test(d) ? d : null;
}

/** The legacy domain to use for NULL rows: the setting's value, or play.nxeon.cloud when blank/invalid. */
export function legacyDomainFrom(setting: string | null | undefined): string {
  return normalizeGameDomain(setting) ?? LEGACY_GAME_DOMAIN;
}

export type ConnectDomainRow = { connectDomain?: string | null };
export type ConnectHostRow = ConnectDomainRow & { subdomain?: string | null };

/** True when the row predates the switch (or was created with it off). */
export function isLegacyDomainRow(row: ConnectDomainRow | null | undefined): boolean {
  return !normalizeGameDomain(row?.connectDomain);
}

/** The domain this row's address lives under. NULL/blank/invalid column = legacy. */
export function connectDomainFor(row: ConnectDomainRow | null | undefined, legacyDomain: string = LEGACY_GAME_DOMAIN): string {
  return normalizeGameDomain(row?.connectDomain) ?? legacyDomainFrom(legacyDomain);
}

/** `<subdomain>.<domain>` for the row, or null when it has no subdomain. */
export function connectHostFor(row: ConnectHostRow | null | undefined, legacyDomain: string = LEGACY_GAME_DOMAIN): string | null {
  const sub = String(row?.subdomain ?? "").trim().toLowerCase();
  if (!sub) return null;
  return `${sub}.${connectDomainFor(row, legacyDomain)}`;
}

export type NewServerDomain = {
  /** The domain a server created right now would be shown under. */
  domain: string;
  /** What to write into `connectDomain` on the new row (null = legacy). */
  stored: string | null;
};

/**
 * Pure decision for a server being created right now. Switch OFF => exactly
 * today (stored NULL, legacy domain). Switch ON => the new domain, stored
 * explicitly so a later switch-off never moves the server back. A new domain
 * that is blank/invalid or equal to the legacy one stores NULL (nothing to
 * distinguish, so do not create a row that looks "new" but is not).
 */
export function pickNewServerDomain(i: { enabled: boolean; newDomain: string | null | undefined; legacyDomain: string | null | undefined }): NewServerDomain {
  const legacy = legacyDomainFrom(i.legacyDomain);
  if (!i.enabled) return { domain: legacy, stored: null };
  const next = normalizeGameDomain(i.newDomain) ?? NEW_GAME_DOMAIN_DEFAULT;
  if (next === legacy) return { domain: legacy, stored: null };
  return { domain: next, stored: next };
