export function knownGameDomains(...domains: (string | null | undefined)[]): string[] {
  const set = new Set<string>();
  for (const d of domains) {
    const n = normalizeGameDomain(d);
    if (n) set.add(n);
  }
  return [...set].sort((a, b) => b.length - a.length);
