 * Split `bob.playnxeon.com` back into `{ subdomain: "bob", domain: "playnxeon.com" }`
 * against the known domains (mc-router log lines, directory hostnames). The
 * subdomain must be ONE label: `a.b.play.nxeon.cloud` is not ours.
 */
export function splitGameHost(host: string | null | undefined, domains: string[]): { subdomain: string; domain: string } | null {
  const h = String(host ?? "").trim().toLowerCase().replace(/\.$/, "");
  for (const d of [...domains].sort((a, b) => b.length - a.length)) {
    if (h.length > d.length + 1 && h.endsWith(`.${d}`)) {
      const sub = h.slice(0, -(d.length + 1));
      if (sub && !sub.includes(".")) return { subdomain: sub, domain: d };
    }
  }
