  for (const z of GAME_DNS_ZONES) {
    if (d === z.zone || d.endsWith(`.${z.zone}`)) return { zone: z.zone, tokenEnv: z.tokenEnv, legacy: false };
  }
  return null;
}

/**
 * Replace the literal legacy domain inside a piece of copy (KB facts, notes)
 * with the domain that applies, so `bob.play.nxeon.cloud` text can follow the
 * row or the "new servers" domain without hand-editing every string.
 */
export function withGameDomain(text: string, domain: string): string {
  return text.split(LEGACY_GAME_DOMAIN).join(domain);
}

