import { getSetting, getSettingBool } from "./settings";
import {
  connectDomainFor,
  connectHostFor,
  knownGameDomains,
  legacyDomainFrom,
  normalizeGameDomain,
  pickNewServerDomain,
  LEGACY_GAME_DOMAIN,
  NEW_GAME_DOMAIN_DEFAULT,
  type ConnectHostRow,
  type NewServerDomain,
} from "./game-domain-rules";

export * from "./game-domain-rules";

/**
 * Server-only half of the per-server game domain (see lib/game-domain-rules.ts
 * for the rules and why). Reads three settings:
 *
 *   free_minecraft_domain     legacy domain for rows with connectDomain NULL
 *                             (play.nxeon.cloud). Changing it still moves every
 *                             LEGACY server, exactly as before; leave it alone.
 *   game_domain_new           domain for servers created while the switch is on
 *                             (default playnxeon.com).
 *   game_domain_new_enabled   the switch, default OFF: until the owner flips it,
 *                             every new server is created exactly as today.
 */

export type GameDomains = {
  /** Domain for connectDomain = NULL rows. */
  legacy: string;
  /** The configured new domain (whether or not the switch is on). */
  newDomain: string;
  enabled: boolean;
  /** What a server created right now gets. */
  forNew: NewServerDomain;
  /** Every domain an address can live under, longest first. */
  all: string[];
};

export async function legacyGameDomain(): Promise<string> {
  return legacyDomainFrom(await getSetting("free_minecraft_domain", LEGACY_GAME_DOMAIN));
}

export async function loadGameDomains(): Promise<GameDomains> {
  const [legacyRaw, newRaw, enabled] = await Promise.all([
    getSetting("free_minecraft_domain", LEGACY_GAME_DOMAIN),
    getSetting("game_domain_new", NEW_GAME_DOMAIN_DEFAULT),
    getSettingBool("game_domain_new_enabled", false),
  ]);
  const legacy = legacyDomainFrom(legacyRaw);
  const newDomain = normalizeGameDomain(newRaw) ?? NEW_GAME_DOMAIN_DEFAULT;
  const forNew = pickNewServerDomain({ enabled, newDomain, legacyDomain: legacy });
  return { legacy, newDomain, enabled, forNew, all: knownGameDomains(legacy, newDomain) };
}

/** What to store in `connectDomain` (and show) for a server being created now. */
export async function newServerDomain(): Promise<NewServerDomain> {
  return (await loadGameDomains()).forNew;
}

/** Async convenience: the row's domain with the legacy setting read for you. */
export async function connectDomainOf(row: { connectDomain?: string | null } | null | undefined): Promise<string> {
  return connectDomainFor(row, await legacyGameDomain());
}

/** Async convenience: `<sub>.<domain>` for the row, or null without a subdomain. */
export async function connectHostOf(row: ConnectHostRow | null | undefined): Promise<string | null> {
  return connectHostFor(row, await legacyGameDomain());
}

