  publicDescription             String?
  // Opt-in showcase extras + moderation (growth batch G6, mkt-031): one optional row
  // per server, see PublicListingMeta. Absent row = listing behaves exactly as before.
  listingMeta                   PublicListingMeta?
  // Customer-requested cross-region moves awaiting admin review (prd-016).
  transferRequests              RegionTransferRequest[]
  customDomain                  String?
  customDomainVerified          Boolean                 @default(false)
  playerSessions                PlayerSession[]
  gameLogCursor                 GameLogCursor?
  // Game runtime truth: cached probe of the game SERVICE inside the VM, the
  // customer/admin run intent, fleet-sweep alert state and the post-provision
  // readiness checklist. See model GameRuntime + lib/game-runtime.ts.
  gameRuntime                   GameRuntime?
  valheimWatch                  ValheimWatch?
  // ---- Live telemetry (nxeon-shipper agent) ----
  // Bearer token the per-server shipper agent authenticates ingest requests
  // with. Same convention as PasswordResetToken/API keys elsewhere: only the
  // SHA-256 hash is stored, the raw token is minted once at provision time,
  // baked into the cloud-init config, and never persisted in the clear. Null
  // until the server's first (re)provision after this feature shipped.
  telemetryTokenHash            String?                 @unique
  telemetryEvents               TelemetryEvent[]
  // Exclusive CPU reservation (admin-only, lib/actions-cpu-reservation.ts). Null
  // for every server that shares its node's CPUs normally.
  cpuReservation                CpuReservation?
}
  engine             String?
  // Crash-loop breaker: while in the future, the watchdog never auto-restarts
  // this container and a dashboard Start is refused with an honest message.
  crashBreakerUntil  DateTime?
  // Dedupe key for crash detection — the `.State.FinishedAt` of the last
  // container exit the watchdog already recorded, so one exit is one event.
  lastExitSeenAt     String?
  // Last `du -sm` of /opt/freemc/servers/<id> (soft disk quota, compared to
  // the `free_minecraft_disk_mb` setting) and when it was measured.
  diskMb             Int?
  diskCheckedAt      DateTime?
  // ---- Funnel milestones (additive, mkt-019, 2026-10-02) ----
  // Stamped ONCE by the health sweep (worker/freemc-health.ts) and never cleared,
  // so the funnel survives the 14-day sample / 90-day event pruning.
  // firstWakeAt       first mc-router wake (a real sleep->awake, >= 2s) seen for this server
  // firstMultiplayerAt first sample with >= 2 players online ("somebody actually played with a friend")
  firstWakeAt        DateTime?
  firstMultiplayerAt DateTime?
  samples            FreeMinecraftSample[]
  events             FreeMinecraftEvent[]
  startRequest       FreeMinecraftStartRequest?
}

