import { cfRequest, cfFindZoneId } from "./cloudflare-dns";
import { legacyGameDomain } from "./game-domain";
import { connectHostFor, dnsZoneFor, type GameDnsZone } from "./game-domain-rules";

/**
 * DNS for PAID game server subdomains (`<name>.<connect domain>`).
 *
 * Distinct from lib/cloudflare-dns.ts, which is built for CUSTOMER-supplied
 * Cloudflare tokens against a CUSTOMER's own zone. This module uses Nxeon's
 * own platform tokens against Nxeon's own zones, and manages SRV records,
 * which lib/cloudflare-dns.ts's CfRecordType doesn't support. It still reuses
 * that module's cfRequest/cfFindZoneId (the generic, token-as-parameter
 * HTTP+auth plumbing) rather than duplicating it.
 *
 * Two zones since 2026-10-08 (lib/game-domain-rules.ts `dnsZoneFor`):
 *   - connectDomain NULL (every server created before the playnxeon.com
 *     switch): `<name>.<free_minecraft_domain>` in the nxeon.cloud zone with
 *     CLOUDFLARE_DNS_API_TOKEN. Byte-for-byte the calls this module made
 *     before the change; legacy records are never moved to another zone.
 *   - connectDomain "playnxeon.com": `<name>.playnxeon.com` in the
 *     playnxeon.com zone with CLOUDFLARE_PLAYNXEON_API_TOKEN.
 *
 * Free-tier Minecraft servers (FreeMinecraftServer) never get per-server
 * records: each domain has ONE wildcard A record (`*.play.nxeon.cloud`,
 * `*.playnxeon.com`) pointing at node-2, where mc-router routes by hostname.
 * This module's exact-name records simply take DNS precedence over that
 * wildcard for the specific names paid customers claim (ordinary DNS
 * specificity, no coordination needed with the free-tier setup).
 *
 * Opt-in + inert: every export is a silent no-op when the zone's token isn't
 * set (or the domain sits in no zone we manage), so this can never become a
 * hard dependency for provisioning, a port-forward save, or a
 * suspend/unsuspend cycle.
 */

/** Injectable I/O so the zone/token routing can be unit-tested with a mocked fetch. */
export type GameDnsDeps = {
  env: Record<string, string | undefined>;
  legacyDomain: () => Promise<string>;
};

const realDeps: GameDnsDeps = { env: process.env, legacyDomain: legacyGameDomain };

const zoneIdCache = new Map<string, string | null>();

function tokenFor(zone: GameDnsZone, deps: GameDnsDeps): string {
  return String(deps.env[zone.tokenEnv] ?? "").trim();
}

async function zoneIdFor(zone: GameDnsZone, token: string): Promise<string | null> {
  const key = `${zone.zone}|${zone.tokenEnv}`;
  if (zoneIdCache.has(key)) return zoneIdCache.get(key) ?? null;
  const id = await cfFindZoneId(token, zone.zone);
  // Cache only a found id: a transient miss must not disable DNS until restart.
  if (id) zoneIdCache.set(key, id);
  return id;
}

/** Test hook: forget cached zone ids. */
export function __resetGameDnsZoneCache(): void {
  zoneIdCache.clear();
}

/**
 * The shared base domain of LEGACY (connectDomain NULL) subdomains. Kept for
 * the callers that only ever dealt with legacy rows; anything that has a row
 * should use connectHostFor/connectDomainFor (lib/game-domain.ts) instead.
 */
export async function gameSubdomainBase(): Promise<string> {
  return legacyGameDomain();
}

type SrvRecord = { id: string; type: string; name: string; data?: { priority: number; weight: number; port: number; target: string } };

async function upsertA(token: string, zone: string, name: string, ip: string): Promise<void> {
  const existing = await cfRequest<{ id: string }[]>(token, "GET", `/zones/${zone}/dns_records?type=A&name=${encodeURIComponent(name)}&per_page=5`);
