 * callers; anything that has a row must use connectHostFor/connectDomainFor
 * (lib/game-domain.ts) so a new-domain server shows its own address.
 */
export async function gameSubdomainBase(): Promise<string> {
  return legacyGameDomain();
}

type SrvRecord = { id: string; type: string; name: string; data?: { priority: number; weight: number; port: number; target: string } };

async function upsertA(token: string, zone: string, name: string, ip: string): Promise<void> {
  const existing = await cfRequest<{ id: string }[]>(token, "GET", `/zones/${zone}/dns_records?type=A&name=${encodeURIComponent(name)}&per_page=5`);
  const body = { type: "A", name, content: ip, ttl: 1, proxied: false };
  if (existing[0]) {
    await cfRequest(token, "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
  } else {
    await cfRequest(token, "POST", `/zones/${zone}/dns_records`, body);
  }
}

/**
 * `host` is the bare `<subdomain>.<base>` name. Confirmed live against the
 * Cloudflare API (2026-08-30, throwaway test record, deleted immediately
 * after): unlike A/MX/TXT, Cloudflare wants the FULL prefixed name
 * (`_minecraft._tcp.<host>`) as the top-level `name`, with `data` holding
 * ONLY `{priority, weight, port, target}` — `service`/`proto`/`name` inside
 * `data` (a shape that's floated around in various docs/examples) is
 * REJECTED with "DNS name is invalid" (code 9000). `target` is the A
 * record's own name (`host`), matching the pattern established above.
 */
async function upsertSrv(token: string, zone: string, host: string, target: string, port: number): Promise<void> {
  const srvName = `_minecraft._tcp.${host}`;
  const existing = await cfRequest<SrvRecord[]>(token, "GET", `/zones/${zone}/dns_records?type=SRV&name=${encodeURIComponent(srvName)}&per_page=5`);
  const body = { type: "SRV", name: srvName, data: { priority: 0, weight: 5, port, target } };
  if (existing[0]) {
    await cfRequest(token, "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
  } else {
    await cfRequest(token, "POST", `/zones/${zone}/dns_records`, body);
  }
}

export type GameDnsTarget = { subdomain: string; connectDomain?: string | null };

/** Resolve zone, token, zone id and host for a row; null = do nothing. */
async function resolve(t: GameDnsTarget, deps: GameDnsDeps): Promise<{ token: string; zoneId: string; host: string } | null> {
  const zone = dnsZoneFor(t.connectDomain);
  if (!zone) return null; // a domain in no zone we manage: never guess
  const token = tokenFor(zone, deps);
  if (!token) return null;
  const legacy = zone.legacy ? await deps.legacyDomain() : undefined;
  const host = connectHostFor({ subdomain: t.subdomain, connectDomain: t.connectDomain }, legacy);
  if (!host) return null;
  const zoneId = await zoneIdFor(zone, token);
  if (!zoneId) return null;
  return { token, zoneId, host };
}

/**
 * Create or update the A record (and, for Java, the SRV record too) for the
 * row's `<subdomain>.<domain>` -> `ip:port`, in the zone of THAT row's domain.
 * Silent no-op if that zone's token isn't configured.
 *
 * `includeSrv` defaults true (every existing Java caller is unaffected).
 * Bedrock Edition has NO SRV support at all — confirmed against Bedrock's own
 * protocol behavior 2026-09-08, unchanged for years and not a Nxeon gap: a
 * Bedrock client never performs the `_minecraft._tcp` SRV lookup Java does,
 * so publishing one for a Bedrock server would just be a dead record. Bedrock
 * players still get a friendly `<subdomain>.<base>` hostname via the A
 * record — they just have to type the port alongside it, same as they would
 * for any host that isn't on Bedrock's (nonexistent) default-port lookup.
 */
export async function upsertMinecraftSubdomainDns(
  opts: { subdomain: string; connectDomain?: string | null; ip: string; port: number; includeSrv?: boolean },
  deps: GameDnsDeps = realDeps,
): Promise<void> {
  const r = await resolve(opts, deps);
  if (!r) return;
  await upsertA(r.token, r.zoneId, r.host, opts.ip);
  if (opts.includeSrv ?? true) await upsertSrv(r.token, r.zoneId, r.host, r.host, opts.port);
}

/**
 * Delete both records for the row's `<subdomain>.<domain>`, if present, in the
 * zone of THAT row's domain only. Idempotent — tolerant of records already
 * missing. A bare string is a legacy (connectDomain NULL) subdomain.
 */
export async function deleteMinecraftSubdomainDns(target: string | GameDnsTarget, deps: GameDnsDeps = realDeps): Promise<void> {
  const t: GameDnsTarget = typeof target === "string" ? { subdomain: target, connectDomain: null } : target;
  const r = await resolve(t, deps);
  if (!r) return;
  const [aRecords, srvRecords] = await Promise.all([
    cfRequest<{ id: string }[]>(r.token, "GET", `/zones/${r.zoneId}/dns_records?type=A&name=${encodeURIComponent(r.host)}&per_page=5`),
    cfRequest<{ id: string }[]>(r.token, "GET", `/zones/${r.zoneId}/dns_records?type=SRV&name=${encodeURIComponent(`_minecraft._tcp.${r.host}`)}&per_page=5`),
  ]);
  for (const rec of [...aRecords, ...srvRecords]) {
    await cfRequest(r.token, "DELETE", `/zones/${r.zoneId}/dns_records/${rec.id}`);
  }
}

