import "server-only";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { FREEMC_GAME_TYPES, getFreeServerStatus } from "@/lib/free-minecraft-control";
import { withServerSsh } from "@/lib/ssh-exec";
import { APP_URL } from "@/components/marketing/StructuredData";
import { btn } from "./cards";
import { esc, nxmHref, type NxmLoad } from "./lib";
import { gameArt } from "./games-lib";

/**
 * /servers/<subdomain> — one public free Minecraft server, with the live
 * page's rules (app/(marketing)/servers/[subdomain]/page.tsx):
 * - privacy gate: only a server that is public AND ready right now renders;
 *   anything else is a plain 404, indistinguishable from a URL that never
 *   existed (metadata goes through the same gate);
 * - live status is best-effort over SSH to freemc-host, bounded to 4 s, and
 *   simply omitted when unknown — the page never hangs or fails on it;
 * - name, tagline and description are the owner's own text (escaped).
 */
async function publicServer(subdomain: string) {
  if (!subdomain) return null;
  const row = await db.freeMinecraftServer.findUnique({
    where: { subdomain },
    select: { subdomain: true, name: true, activeGameType: true, status: true, isPublic: true, publicTagline: true, publicDescription: true, containerName: true },
  });
  if (!row || !row.isPublic || row.status !== "READY") return null;
  return row;
}

async function liveStatus(containerName: string): Promise<{ running: boolean; players: { online: number; max: number } | null } | null> {
  const withTimeout = <T,>(p: Promise<T>, ms: number): Promise<T> =>
    new Promise((resolve, reject) => {
      const t = setTimeout(() => reject(new Error("timeout")), ms);
      p.then((v) => { clearTimeout(t); resolve(v); }, (e) => { clearTimeout(t); reject(e); });
    });
  try {
    const host = await db.server.findFirst({
      where: { hostname: "freemc-host" },
      select: { id: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
    });
    if (!host) return null;
    return await withTimeout(withServerSsh(host, (conn) => getFreeServerStatus(conn, containerName)), 4_000);
  } catch {
    return null;
  }
}

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const s = await publicServer(p.subdomain);
  if (!s) notFound();
  const [domain, live] = await Promise.all([getSetting("free_minecraft_domain", "play.nxeon.cloud"), liveStatus(s.containerName)]);
  const preset = FREEMC_GAME_TYPES[s.activeGameType] ?? FREEMC_GAME_TYPES.vanilla;
  const name = s.name || s.subdomain;
  const address = `${s.subdomain}.${domain}`;
  const art = gameArt("minecraft");
  const status = !live ? ""
    : live.running
      ? `<span class="au-chip sv-live"><i class="d"></i>Awake · ${live.players?.online ?? 0} / ${live.players?.max ?? "?"} online</span>`
      : `<span class="au-chip sv-sleep"><i class="d"></i>Asleep · connecting wakes it up</span>`;
  return {
    slots: {
      "art.style": "",
      back: nxmHref("/servers"),
      "cover:html": art.cover ? `<img class="sv-cover" src="${esc(art.cover)}" alt="" width="112" height="150">` : "",
      game: "Minecraft",
      mode: preset.label,
      "status:html": status,
      name,
      "tagline:html": s.publicTagline ? `<p class="sv-tag">${esc(s.publicTagline)}</p>` : "",
      address,
      desc: s.publicDescription || "The owner hasn’t added a description yet.",
      "mode.desc": preset.description,
      "mode.note:html": preset.setupNote ? `<p class="sv-note">${esc(preset.setupNote)}</p>` : "",
      "join.last": live && live.running
        ? "Join. The server is awake right now."
        : "Join. If the server is asleep, your first connection wakes it up.",
      "final:html": btn(true, "/dashboard/free-minecraft", "Create my free server")
        + `<a class="nxm-glassbtn" href="${esc(nxmHref("/servers"))}"><span class="nxm-bt">Browse more servers</span></a>`,
    },
    jsonLd: [{
      "@context": "https://schema.org", "@type": "GameServer", name, url: `${APP_URL}/servers/${s.subdomain}`,
      game: { "@type": "VideoGame", name: "Minecraft" },
      ...(live && live.running ? { serverStatus: "https://schema.org/Online", ...(live.players ? { playersOnline: live.players.online } : {}) } : {}),
    }],
    crumb: name,
  };
}

export async function meta(p: Record<string, string>) {
  const s = await publicServer(p.subdomain);
  if (!s) notFound();
  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const preset = FREEMC_GAME_TYPES[s.activeGameType] ?? FREEMC_GAME_TYPES.vanilla;
  const name = s.name || s.subdomain;
  const art = gameArt("minecraft");
  return {
    title: `${name} — ${preset.label} Minecraft Server`,
    description: s.publicTagline || `Join ${name}, a free ${preset.label} Minecraft server at ${s.subdomain}.${domain} — hosted free on Nxeon.`,
    crumb: name,
    ...(art.hero ? { image: art.hero } : {}),
  };
}

