import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import {
  LEGACY_GAME_DOMAIN,
  NEW_GAME_DOMAIN_DEFAULT,
  normalizeGameDomain,
  legacyDomainFrom,
  isLegacyDomainRow,
  connectDomainFor,
  connectHostFor,
  pickNewServerDomain,
  knownGameDomains,
  splitGameHost,
  rowForGameHost,
  dnsZoneFor,
  withGameDomain,
  gameDomainCopy,
} from "../lib/game-domain-rules.ts";
import { connectAddress } from "../lib/nx/connect-address.ts";

const LEGACY = { subdomain: "bob", connectDomain: null };
const NEW = { subdomain: "alice", connectDomain: "playnxeon.com" };

// ---- normalisation ----

test("normalizeGameDomain: trims, lowercases, strips wildcard and dots; rejects junk", () => {
  assert.equal(normalizeGameDomain(" PlayNxeon.com. "), "playnxeon.com");
  assert.equal(normalizeGameDomain("*.playnxeon.com"), "playnxeon.com");
  assert.equal(normalizeGameDomain(".play.nxeon.cloud"), "play.nxeon.cloud");
  for (const bad of ["", null, undefined, "https://x.com", "no spaces.com x", "localhost", "a..b.com"]) {
    assert.equal(normalizeGameDomain(bad as string), null, String(bad));
  }
});

test("legacyDomainFrom: a blank/invalid legacy setting falls back to play.nxeon.cloud, never `bob.`", () => {
  assert.equal(legacyDomainFrom(""), LEGACY_GAME_DOMAIN);
  assert.equal(legacyDomainFrom("garbage value"), LEGACY_GAME_DOMAIN);
  assert.equal(legacyDomainFrom("play.nxeon.cloud"), "play.nxeon.cloud");
  assert.equal(connectHostFor(LEGACY, ""), "bob.play.nxeon.cloud");
});

// ---- per-row address: legacy unchanged, new on its own domain ----

test("legacy row (connectDomain NULL) always shows <name>.play.nxeon.cloud", () => {
  assert.equal(isLegacyDomainRow(LEGACY), true);
  assert.equal(connectDomainFor(LEGACY), "play.nxeon.cloud");
  assert.equal(connectHostFor(LEGACY), "bob.play.nxeon.cloud");
  assert.equal(connectHostFor(LEGACY, "play.nxeon.cloud"), "bob.play.nxeon.cloud");
  // undefined (a select that predates the column) is legacy too
  assert.equal(connectHostFor({ subdomain: "bob", connectDomain: undefined }), "bob.play.nxeon.cloud");
});

test("new row shows <name>.playnxeon.com regardless of the legacy setting", () => {
  assert.equal(isLegacyDomainRow(NEW), false);
  assert.equal(connectHostFor(NEW), "alice.playnxeon.com");
  assert.equal(connectHostFor(NEW, "play.nxeon.cloud"), "alice.playnxeon.com");
});

test("no subdomain => no host", () => {
  assert.equal(connectHostFor({ subdomain: null, connectDomain: "playnxeon.com" }), null);
  assert.equal(connectHostFor({ subdomain: "", connectDomain: null }), null);
});

// ---- the switch ----

test("switch OFF: a new server is created exactly as today (stored NULL, legacy domain)", () => {
  assert.deepEqual(pickNewServerDomain({ enabled: false, newDomain: "playnxeon.com", legacyDomain: "play.nxeon.cloud" }), { domain: "play.nxeon.cloud", stored: null });
});

test("switch ON: new servers get playnxeon.com, stored explicitly", () => {
  assert.deepEqual(pickNewServerDomain({ enabled: true, newDomain: "playnxeon.com", legacyDomain: "play.nxeon.cloud" }), { domain: "playnxeon.com", stored: "playnxeon.com" });
});

test("switch ON with a blank/invalid new domain uses the default, never a broken address", () => {
  assert.deepEqual(pickNewServerDomain({ enabled: true, newDomain: "", legacyDomain: "play.nxeon.cloud" }), { domain: NEW_GAME_DOMAIN_DEFAULT, stored: NEW_GAME_DOMAIN_DEFAULT });
});

test("switch ON but new == legacy stores NULL (nothing to distinguish)", () => {
  assert.deepEqual(pickNewServerDomain({ enabled: true, newDomain: "play.nxeon.cloud", legacyDomain: "play.nxeon.cloud" }), { domain: "play.nxeon.cloud", stored: null });
});

test("rollback: once stored, a row keeps its domain after the switch goes OFF", () => {
  // The row is the source of truth; the switch only feeds pickNewServerDomain for NEW rows.
  assert.equal(connectHostFor(NEW, "play.nxeon.cloud"), "alice.playnxeon.com");
});

test("rename keeps the row's domain: only the subdomain changes", () => {
  const renamedLegacy = { ...LEGACY, subdomain: "bobby" };
  const renamedNew = { ...NEW, subdomain: "alicia" };
  assert.equal(connectHostFor(renamedLegacy), "bobby.play.nxeon.cloud");
  assert.equal(connectHostFor(renamedNew), "alicia.playnxeon.com");
});

// ---- host parsing (mc-router logs, directory) ----

test("splitGameHost: one label in front of a known domain, longest domain first", () => {
  const all = knownGameDomains("play.nxeon.cloud", "playnxeon.com");
  assert.deepEqual(all, ["play.nxeon.cloud", "playnxeon.com"]);
  assert.deepEqual(splitGameHost("bob.play.nxeon.cloud", all), { subdomain: "bob", domain: "play.nxeon.cloud" });
  assert.deepEqual(splitGameHost("Bob.PlayNxeon.com.", all), { subdomain: "bob", domain: "playnxeon.com" });
  assert.equal(splitGameHost("a.b.playnxeon.com", all), null);
  assert.equal(splitGameHost("playnxeon.com", all), null);
  assert.equal(splitGameHost("bob.example.com", all), null);
});

test("rowForGameHost: a host only matches the row on ITS OWN domain", () => {
  const rows = new Map([
    ["bob", { subdomain: "bob", connectDomain: null }],
    ["alice", { subdomain: "alice", connectDomain: "playnxeon.com" }],
  ]);
  const d = { legacy: "play.nxeon.cloud", all: knownGameDomains("play.nxeon.cloud", "playnxeon.com") };
  assert.equal(rowForGameHost("bob.play.nxeon.cloud", rows, d)?.subdomain, "bob");
  assert.equal(rowForGameHost("alice.playnxeon.com", rows, d)?.subdomain, "alice");
  assert.equal(rowForGameHost("bob.playnxeon.com", rows, d), undefined, "legacy bob is not reachable on the new domain");
  assert.equal(rowForGameHost("alice.play.nxeon.cloud", rows, d), undefined, "new alice is not on the legacy domain");
});

// ---- DNS zone routing ----

test("dnsZoneFor: legacy rows ALWAYS use the nxeon.cloud zone + platform token (exactly as before)", () => {
  assert.deepEqual(dnsZoneFor(null), { zone: "nxeon.cloud", tokenEnv: "CLOUDFLARE_DNS_API_TOKEN", legacy: true });
  assert.deepEqual(dnsZoneFor(undefined), { zone: "nxeon.cloud", tokenEnv: "CLOUDFLARE_DNS_API_TOKEN", legacy: true });
  assert.deepEqual(dnsZoneFor(""), { zone: "nxeon.cloud", tokenEnv: "CLOUDFLARE_DNS_API_TOKEN", legacy: true });
});

test("dnsZoneFor: playnxeon.com rows use the playnxeon.com zone + CLOUDFLARE_PLAYNXEON_API_TOKEN", () => {
  assert.deepEqual(dnsZoneFor("playnxeon.com"), { zone: "playnxeon.com", tokenEnv: "CLOUDFLARE_PLAYNXEON_API_TOKEN", legacy: false });
  assert.deepEqual(dnsZoneFor("eu.playnxeon.com"), { zone: "playnxeon.com", tokenEnv: "CLOUDFLARE_PLAYNXEON_API_TOKEN", legacy: false });
});

test("dnsZoneFor: a domain in no zone we manage does nothing (null), never a guess", () => {
  assert.equal(dnsZoneFor("example.com"), null);
  assert.equal(dnsZoneFor("notplaynxeon.com"), null);
});

// ---- copy ----

test("gameDomainCopy: switch OFF returns the text byte-for-byte", () => {
  const t = "- Address: <name>.play.nxeon.cloud, no port needed.";
  assert.equal(gameDomainCopy(t, { legacy: "play.nxeon.cloud", newStored: null }), t);
});

test("gameDomainCopy: switch ON names the new domain and says older servers keep theirs", () => {
  const out = gameDomainCopy("- Address: <name>.play.nxeon.cloud, no port needed.", { legacy: "play.nxeon.cloud", newStored: "playnxeon.com" });
  assert.match(out, /<name>\.playnxeon\.com, no port needed/);
  assert.match(out, /keep their <name>\.play\.nxeon\.cloud address/);
  assert.equal(withGameDomain("yourname.play.nxeon.cloud", "playnxeon.com"), "yourname.playnxeon.com");
});

// ---- the shared connect-address builder (dashboard, services list, grants) ----

const paid = (over: Partial<Parameters<typeof connectAddress>[0]>) => ({
  gamePlanId: "gp", subdomain: null, connectDomain: null, sshPort: null, dedicatedIp: null,
  portForwards: [], node: { publicIp: "198.51.100.9" }, osTemplate: null, gamePlan: { gameFamily: "minecraft" }, ...over,
});

test("connectAddress: legacy server keeps play.nxeon.cloud, new server shows playnxeon.com", () => {
  assert.equal(connectAddress(paid({ subdomain: "bob" }), "play.nxeon.cloud").address, "bob.play.nxeon.cloud");
  assert.equal(connectAddress(paid({ subdomain: "alice", connectDomain: "playnxeon.com" }), "play.nxeon.cloud").address, "alice.playnxeon.com");
});

// ---- source guards: no stray global reads that would move every server ----

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (name === "node_modules" || name.startsWith(".")) continue;
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(name)) out.push(p);
  }
  return out;
}

test("nothing builds an address from the raw free_minecraft_domain setting except lib/game-domain.ts", () => {
  const offenders = ["lib", "worker", "app", "components", "scripts"]
    .flatMap((d) => walk(d))
    .filter((f) => !f.endsWith("lib/game-domain.ts"))
    .filter((f) => /getSetting\(\s*["']free_minecraft_domain["']|key:\s*["']free_minecraft_domain["']\s*}\s*}\)/.test(readFileSync(f, "utf8")));
  assert.deepEqual(offenders, []);
});

test("no UI/server code hard-codes a `.play.nxeon.cloud` suffix in an address", () => {
  const offenders = ["lib", "worker", "app", "components"]
    .flatMap((d) => walk(d))
    .filter((f) => !/lib\/game-domain(-rules)?\.ts$/.test(f))
    .filter((f) => /\$\{[^}]+\}\.play\.nxeon\.cloud|>\.play\.nxeon\.cloud</.test(readFileSync(f, "utf8")));
  // vm-move keeps a legacy fallback only for facts objects built without connectHost.
  assert.deepEqual(offenders.filter((f) => !f.endsWith("lib/vm-move/engine.ts")), []);
});

test("the availability check is domain-agnostic: one namespace across both domains", () => {
  const src = readFileSync("lib/game-subdomain.ts", "utf8");
  assert.ok(!/connectDomain/.test(src), "isSubdomainAvailable must not filter by domain");
  assert.match(src, /freeMinecraftServer\.findFirst/);
  assert.match(src, /server\.findFirst/);
});

test("every recreateGameTypeContainer caller passes the row's own domain", () => {
  for (const f of ["lib/actions-free-minecraft.ts", "lib/actions-freemc-mods.ts", "lib/actions-freemc-worlds.ts", "scripts/freemc/rollout/03-recreate-asleep.ts"]) {
    const src = readFileSync(f, "utf8");
    assert.ok(/connectDomainOf\(row\)|connectDomainFor\(row|newServerDomain\(\)/.test(src), f);
  }
  const create = readFileSync("lib/actions-free-minecraft.ts", "utf8");
  assert.match(create, /newServerDomain\(\)/, "claim decides the domain once");
  assert.match(create, /connectDomain \} : \{\}\)/, "and stores it on the row");
});

test("paid checkout stores the decided domain on the new Server row", () => {
  const src = readFileSync("lib/game-order.ts", "utf8");
  assert.match(src, /const gameDomain = await newServerDomain\(\)/);
  assert.match(src, /quote\.connectDomainStored \? \{ connectDomain: quote\.connectDomainStored \}/);
});

