import { test, beforeEach, afterEach } from "node:test";
import assert from "node:assert/strict";
import {
  upsertMinecraftSubdomainDns,
  deleteMinecraftSubdomainDns,
  __resetGameDnsZoneCache,
  type GameDnsDeps,
} from "../lib/game-subdomain-dns.ts";
import { planGameServerDnsOp } from "../worker/game-subdomain-sync.ts";

/**
 * Mocked Cloudflare: proves which zone, token and record names the DNS layer
 * touches for a legacy row vs a playnxeon.com row. No network.
 */
type Call = { method: string; path: string; token: string; body: unknown };
let calls: Call[] = [];
let existing: Record<string, { id: string }[]> = {};
const realFetch = globalThis.fetch;

const LEGACY_TOKEN = "legacy-token-x";
const NEW_TOKEN = "playnxeon-token-y";
const ZONES: Record<string, string> = { "nxeon.cloud": "zone-nxeon-cloud", "playnxeon.com": "zone-playnxeon" };

beforeEach(() => {
  calls = [];
  existing = {};
  __resetGameDnsZoneCache();
  globalThis.fetch = (async (url: string | URL, init?: RequestInit) => {
    const u = new URL(String(url));
    const path = u.pathname.replace("/client/v4", "") + u.search;
    const token = String((init?.headers as Record<string, string>)?.Authorization ?? "").replace("Bearer ", "");
    const method = init?.method ?? "GET";
    calls.push({ method, path, token, body: init?.body ? JSON.parse(String(init.body)) : undefined });
    let result: unknown = {};
    if (path.startsWith("/zones?name=")) {
      const name = decodeURIComponent(u.searchParams.get("name") ?? "");
      result = ZONES[name] ? [{ id: ZONES[name], name }] : [];
    } else if (method === "GET" && path.includes("/dns_records?")) {
      const key = `${u.searchParams.get("type")} ${u.searchParams.get("name")}`;
      result = existing[key] ?? [];
    }
    return new Response(JSON.stringify({ success: true, errors: [], result }), { status: 200 });
  }) as typeof fetch;
});
afterEach(() => { globalThis.fetch = realFetch; });

const deps = (env: Record<string, string | undefined>): GameDnsDeps => ({ env, legacyDomain: async () => "play.nxeon.cloud" });
const BOTH = { CLOUDFLARE_DNS_API_TOKEN: LEGACY_TOKEN, CLOUDFLARE_PLAYNXEON_API_TOKEN: NEW_TOKEN };

const touches = (needle: string) => calls.some((c) => c.path.includes(needle) || JSON.stringify(c.body ?? "").includes(needle));

test("legacy row: A + SRV created in the nxeon.cloud zone with the platform token, exactly as before", async () => {
  await upsertMinecraftSubdomainDns({ subdomain: "bob", connectDomain: null, ip: "198.51.100.9", port: 25601 }, deps(BOTH));
  assert.ok(calls.every((c) => c.token === LEGACY_TOKEN), "only the legacy token");
  assert.deepEqual(calls[0], { method: "GET", path: "/zones?name=nxeon.cloud&status=active&per_page=5", token: LEGACY_TOKEN, body: undefined });
  const posts = calls.filter((c) => c.method === "POST");
  assert.deepEqual(posts.map((c) => c.path), ["/zones/zone-nxeon-cloud/dns_records", "/zones/zone-nxeon-cloud/dns_records"]);
  assert.deepEqual(posts[0].body, { type: "A", name: "bob.play.nxeon.cloud", content: "198.51.100.9", ttl: 1, proxied: false });
  assert.deepEqual(posts[1].body, { type: "SRV", name: "_minecraft._tcp.bob.play.nxeon.cloud", data: { priority: 0, weight: 5, port: 25601, target: "bob.play.nxeon.cloud" } });
  assert.ok(!touches("playnxeon"), "never the new zone");
});

test("legacy row: existing records are updated in place (PUT), never deleted/recreated", async () => {
  existing["A bob.play.nxeon.cloud"] = [{ id: "rec-a" }];
  existing["SRV _minecraft._tcp.bob.play.nxeon.cloud"] = [{ id: "rec-srv" }];
  await upsertMinecraftSubdomainDns({ subdomain: "bob", connectDomain: null, ip: "198.51.100.10", port: 25602 }, deps(BOTH));
  assert.deepEqual(calls.filter((c) => c.method !== "GET").map((c) => `${c.method} ${c.path}`), [
    "PUT /zones/zone-nxeon-cloud/dns_records/rec-a",
    "PUT /zones/zone-nxeon-cloud/dns_records/rec-srv",
  ]);
});

test("playnxeon.com row: records go to the playnxeon.com zone with CLOUDFLARE_PLAYNXEON_API_TOKEN only", async () => {
  await upsertMinecraftSubdomainDns({ subdomain: "alice", connectDomain: "playnxeon.com", ip: "203.0.113.5", port: 25565 }, deps(BOTH));
  assert.ok(calls.every((c) => c.token === NEW_TOKEN), "only the playnxeon token");
  assert.equal(calls[0].path, "/zones?name=playnxeon.com&status=active&per_page=5");
  const posts = calls.filter((c) => c.method === "POST");
  assert.deepEqual(posts.map((c) => (c.body as { name: string }).name), ["alice.playnxeon.com", "_minecraft._tcp.alice.playnxeon.com"]);
  assert.ok(posts.every((c) => c.path === "/zones/zone-playnxeon/dns_records"));
  assert.ok(!touches("zone-nxeon-cloud") && !touches("nxeon.cloud"), "never the nxeon.cloud zone");
});

test("Bedrock / hostname-only families: A record only, no SRV, on either domain", async () => {
  await upsertMinecraftSubdomainDns({ subdomain: "bed", connectDomain: "playnxeon.com", ip: "203.0.113.5", port: 19132, includeSrv: false }, deps(BOTH));
  assert.deepEqual(calls.filter((c) => c.method === "POST").map((c) => (c.body as { type: string }).type), ["A"]);
});

test("delete for a playnxeon.com row only looks up and removes ITS names in ITS zone", async () => {
  existing["A alice.playnxeon.com"] = [{ id: "a1" }];
  existing["SRV _minecraft._tcp.alice.playnxeon.com"] = [{ id: "s1" }];
  // A same-named legacy record exists too: it must not be found or touched.
  existing["A alice.play.nxeon.cloud"] = [{ id: "legacy-a" }];
  await deleteMinecraftSubdomainDns({ subdomain: "alice", connectDomain: "playnxeon.com" }, deps(BOTH));
  assert.deepEqual(calls.filter((c) => c.method === "DELETE").map((c) => c.path), ["/zones/zone-playnxeon/dns_records/a1", "/zones/zone-playnxeon/dns_records/s1"]);
  assert.ok(!touches("legacy-a") && !touches("play.nxeon.cloud"));
});

test("delete for a legacy row stays in the legacy zone and never touches playnxeon.com", async () => {
  existing["A bob.play.nxeon.cloud"] = [{ id: "a-legacy" }];
  existing["A bob.playnxeon.com"] = [{ id: "a-new-squatter" }];
  await deleteMinecraftSubdomainDns({ subdomain: "bob", connectDomain: null }, deps(BOTH));
  assert.deepEqual(calls.filter((c) => c.method === "DELETE").map((c) => c.path), ["/zones/zone-nxeon-cloud/dns_records/a-legacy"]);
  assert.ok(!touches("playnxeon"));
});

test("missing playnxeon token: silent no-op for new rows (provisioning never blocks), legacy unaffected", async () => {
  await upsertMinecraftSubdomainDns({ subdomain: "alice", connectDomain: "playnxeon.com", ip: "203.0.113.5", port: 25565 }, deps({ CLOUDFLARE_DNS_API_TOKEN: LEGACY_TOKEN }));
  await deleteMinecraftSubdomainDns({ subdomain: "alice", connectDomain: "playnxeon.com" }, deps({ CLOUDFLARE_DNS_API_TOKEN: LEGACY_TOKEN }));
  assert.equal(calls.length, 0, "no call at all, and in particular never with the legacy token");
  await upsertMinecraftSubdomainDns({ subdomain: "bob", connectDomain: null, ip: "198.51.100.9", port: 25601 }, deps({ CLOUDFLARE_DNS_API_TOKEN: LEGACY_TOKEN }));
  assert.ok(calls.length > 0 && calls.every((c) => c.token === LEGACY_TOKEN));
});

test("missing legacy token: legacy rows no-op exactly as before; new rows still work", async () => {
  await upsertMinecraftSubdomainDns({ subdomain: "bob", connectDomain: null, ip: "198.51.100.9", port: 25601 }, deps({ CLOUDFLARE_PLAYNXEON_API_TOKEN: NEW_TOKEN }));
  assert.equal(calls.length, 0);
});

test("a domain in no managed zone does nothing at all", async () => {
  await upsertMinecraftSubdomainDns({ subdomain: "x", connectDomain: "example.com", ip: "203.0.113.5", port: 25565 }, deps(BOTH));
  await deleteMinecraftSubdomainDns({ subdomain: "x", connectDomain: "example.com" }, deps(BOTH));
  assert.equal(calls.length, 0);
});

test("zone not visible to the token: no-op, and the miss is not cached forever", async () => {
  const saved = ZONES["playnxeon.com"];
  delete ZONES["playnxeon.com"];
  try {
    await upsertMinecraftSubdomainDns({ subdomain: "alice", connectDomain: "playnxeon.com", ip: "203.0.113.5", port: 25565 }, deps(BOTH));
    assert.equal(calls.filter((c) => c.method !== "GET").length, 0);
  } finally {
    ZONES["playnxeon.com"] = saved;
  }
  calls = [];
  await upsertMinecraftSubdomainDns({ subdomain: "alice", connectDomain: "playnxeon.com", ip: "203.0.113.5", port: 25565 }, deps(BOTH));
  assert.ok(calls.some((c) => c.method === "POST"), "works once the zone appears");
});

test("sync plan passes the row's own connectDomain through (legacy stays NULL)", () => {
  assert.deepEqual(planGameServerDnsOp({ subdomain: "bob", connectDomain: null }, { ip: "1.2.3.4", port: 25601 }, true),
    { kind: "upsert", args: { subdomain: "bob", connectDomain: null, ip: "1.2.3.4", port: 25601, includeSrv: true } });
  assert.deepEqual(planGameServerDnsOp({ subdomain: "alice", connectDomain: "playnxeon.com" }, null, true),
    { kind: "delete", args: { subdomain: "alice", connectDomain: "playnxeon.com" } });
});

