#!/usr/bin/env node
// playnxeon.com DNS prep for the per-server game domain (lib/game-domain.ts).
//
// DRY-RUN BY DEFAULT: prints exactly which records it would create or change in
// the playnxeon.com Cloudflare zone and changes nothing. Only `--apply` writes.
//
// It manages exactly three names and never deletes anything:
//   *.playnxeon.com  A      -> node-2 (free-tier mc-router), DNS-only
//   playnxeon.com    A      -> the primary (nginx 301 to /game-servers), DNS-only
//   www.playnxeon.com CNAME -> playnxeon.com, DNS-only
// Every other record in the zone is listed as "left alone". Per-server game
// records (<name>.playnxeon.com A + _minecraft._tcp SRV) are NOT created here:
// worker/game-subdomain-sync.ts makes them per paid server.
//
// Usage (on the primary, as root):
//   node scripts/playnxeon-dns-prep.mjs --env-file /root/secrets/cloudflare-playnxeon.env
//   node scripts/playnxeon-dns-prep.mjs --env-file /root/secrets/cloudflare-playnxeon.env --apply
// Options:
//   --env-file <path>   file holding CLOUDFLARE_PLAYNXEON_API_TOKEN= or CLOUDFLARE_API_TOKEN=
//                       (else the CLOUDFLARE_PLAYNXEON_API_TOKEN env var is used)
//   --node2-ip <ip>     wildcard target; default = what *.play.nxeon.cloud resolves to today
//                       (the legacy free-tier wildcard), falling back to 178.63.94.114
//   --primary-ip <ip>   root/www target; default 51.79.162.96
//   --apply             actually write
// The token is never printed.

import { readFileSync } from "node:fs";
import { Resolver } from "node:dns/promises";
import { randomBytes } from "node:crypto";

const ZONE = "playnxeon.com";
const NODE2_FALLBACK = "178.63.94.114";
const PRIMARY_DEFAULT = "51.79.162.96";
const API = "https://api.cloudflare.com/client/v4";

const args = process.argv.slice(2);
const flag = (n) => args.includes(n);
const opt = (n) => { const i = args.indexOf(n); return i > -1 ? args[i + 1] : undefined; };
const APPLY = flag("--apply");
const IPV4 = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;

function loadToken() {
  const file = opt("--env-file");
  if (file) {
    const txt = readFileSync(file, "utf8");
    for (const key of ["CLOUDFLARE_PLAYNXEON_API_TOKEN", "CLOUDFLARE_API_TOKEN"]) {
